{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"Rent increases are limited to the lower of 3% per year or 80% of the 12-month change in the Consumer Price Index, and no increase is allowed if the CPI is negative. Owners must give written notice of the ordinance and tenant rights with any rent increase.","key_value":"lower of 3% per year or 80% of 12-month CPI change; 0% if CPI is negative","coverage_conditions":"Residential rental property and mobile home parks, except residential buildings constructed after February 1, 1995 and mobile home spaces offered for rent after January 1, 1990.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1995-02-01","basis":"construction"},{"type":"other","text":"mobile home spaces offered for rent after January 1, 1990"}],"per_tenancy":null,"coverage_quotes":["The rent cap does not apply to residential buildings constructed after February 1, 1995, or to mobile home spaces offered for rent after January 1, 1990."]},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990. Owners may petition the City Manager for relief from the cap.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days, an owner may not terminate a tenancy without just cause, stated in a written notice, and must first give the tenant notice and time to fix a violation. For no-fault terminations the owner must give 3 months of relocation assistance or waive the final 3 months of rent.","key_value":"3 months' relocation assistance or final 3 months' rent waived","coverage_conditions":"Tenancies after 30 days, except housing produced in the last 15 years, deed-restricted affordable housing, hotel and transient occupancy, hospital and care facilities, dormitories and other shared living quarters.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"other","text":"deed-restricted affordable housing"}],"per_tenancy":"Applies to a tenancy after 30 days.","coverage_quotes":["The Just Cause Ordinance shall not apply to certain types of residential property, including housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters."]},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; other shared living quarters.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
